/// C-FFI dispatch descriptor for SunSpec model 123. A C `SunspecModelBinding` points
/// at this static, so the service functions dispatch with no model-id lookup.
#[unsafe(no_mangle)]
pub static SUNSPEC_MODEL_123: StaticModelSpec = StaticModelSpec {
    id: 123,
    length: model_123_c_length,
    writable: true,
    visit_read: model_123_c_visit_read,
    visit_write: model_123_c_visit_write,
};

fn model_123_c_length(_repeat_count_0: u16, _repeat_count_1: u16) -> u16 {
    (Model123).model_length()
}

/// # Safety
/// `adapter` must be null or point to a live `Model123CallbackAdapter`, valid for the
/// duration of the call.
unsafe fn model_123_c_visit_read(
    adapter: *const c_void,
    _repeat_count_0: u16,
    _repeat_count_1: u16,
    cursor: &mut Cursor<ModbusException>,
    buffer: &mut WritableRegisterBuffer<'_>,
) {
    let model = Model123;
    // SAFETY: as required by this function's own contract.
    let adapter = unsafe { (adapter as *const Model123CallbackAdapter).as_ref() };
    cursor.visit_source_block(model.model_length(), |offset, from, len| {
        let mut block = buffer.slice(from, len);
        match adapter {
            Some(adapter) => model.traverse_points_read(adapter, &mut block, offset),
            None => {
                block.fill(&[0xff, 0xff]);
                Ok(())
            }
        }
    });
}

/// # Safety
/// As for [`model_123_c_visit_read`], and `adapter` must be uniquely borrowable for the call.
unsafe fn model_123_c_visit_write(
    adapter: *mut c_void,
    _repeat_count_0: u16,
    _repeat_count_1: u16,
    cursor: &mut Cursor<ModbusException>,
    buffer: &ReadableRegisterBuffer<'_>,
) {
    let model = Model123;
    // SAFETY: as required by this function's own contract.
    let adapter = unsafe { (adapter as *mut Model123CallbackAdapter).as_mut() };
    cursor.visit_source_block(model.model_length(), |offset, from, len| match adapter {
        Some(adapter) => model.traverse_points_write(adapter, &buffer.slice(from, len), offset),
        None => Err(ModbusException::IllegalDataAddress),
    });
}

